const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let world,saveProblem=false,loadFailed=false;try{const saved=localStorage.getItem('garage-vivant-v1');if(saved){const input=JSON.parse(saved);if(input.version!==VERSION){try{if(!localStorage.getItem('garage-vivant-before-v5'))localStorage.setItem('garage-vivant-before-v5',saved);}catch{}}world=restore(input);}else world=createWorld();}catch{world=createWorld();saveProblem=true;loadFailed=true;}
let selected=world.people[0].id,view='map',pair=null,metric='affinity',filter='all',lastUI=0,lastSaved=0,tabInactive=false,labValues=false,rawJournal=false;
const viewPositions=createViewPositions(),personPositions=createViewPositions();
