canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const hits=screenPositions.filter(p=>Math.hypot(p.x-x,p.y-y)<p.r+10).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y));if(hits.length)select(hits[0].id);});
document.addEventListener('visibilitychange',()=>{tabInactive=document.hidden;playback.budget=0;playback.last=performance.now();updatePositions(world.people,displayPos,{visible:false});save();});window.addEventListener('pagehide',save);
function filteredJournal(){
 const category=e=>e.session?(['practice','jam','write'].includes(e.key)?'music':e.key==='social'?'relations':'life'):['music','jam','project','song'].includes(e.type)?'music':['social','conflict','support','romance'].includes(e.type)?'relations':e.type==='group'?'groups':['show','booking','season'].includes(e.type)?'shows':'life';
 return journalEntries(world,{raw:rawJournal,filter,selected}).filter(e=>journalTypes.has(category(e))&&!(hideRest&&e.session&&['sleep','relax'].includes(e.key)));
}
function renderShows(){
 replacePreserving('#show-setup',showSetupHTML(world,showPlan));replacePreserving('#season-report',seasonHTML(world));
 const show=world.performance;if(show?.status==='playing')showingPerformance=true;$('#performance-wrap').hidden=!show||!showingPerformance;$('#show-setup').hidden=!!show&&showingPerformance;$('#season-report').hidden=show?.status==='playing';
 if(!show)return;
 replacePreserving('#show-status',showStatusHTML(world));$('#show-pause').textContent=showPaused||playback.speed===0?'▶ Reprendre':'Ⅱ Pause';$('#show-pause').disabled=show.status!=='playing';
 replacePreserving('#show-feed',show.events.filter(e=>['impact','reaction','curse','final'].includes(e.type)).slice(-5).map(e=>`<p data-stable="show-event-${e.id}">${esc(e.text)}</p>`).join('')||'<p>Le band se prépare. Les cartes arrivent dans leur ordre musical.</p>');
 replacePreserving('#show-explanation',show.events.filter(e=>e.type!=='card').map(e=>`<p data-stable="show-cause-${e.id}"><b>${(e.tick/60).toFixed(1)} s</b> · ${esc(e.text)}${e.type==='impact'?` · ${e.touched} touchés, +${e.gain} points de jauges`:''}</p>`).join(''));
 $('#sound').checked=soundEnabled;$('#reduced-effects').checked=reducedEffects;
 if(selectedFan){const fan=show.fans.find(f=>f.id===selectedFan);if(fan)$('#fan-detail').textContent=`${fan.name} · aime ${fan.style} · sensible à ${SKILLS[fan.instrument]} · ${round(fan.meter)}/100 · ${fan.reacted?'conquis':'encore à toucher'} · réaction : ${({euphoria:'euphorie',emotion:'émotion',trance:'transe'})[fan.reaction]}`;}
 drawStage($('#stage'),show,{reduced:reducedEffects,selectedFan});
}
function submit(cmd){const r=command(world,cmd);notify(r.message);render();if(view==='groups')renderGroups();if(view==='shows')renderShows();save();return r;}
function launchPreview(replay=false){const r=submit(replay?{type:'replay'}:{type:'preview',...showPlan});if(r.ok){showingPerformance=true;showPaused=false;showBudget=0;setPlaybackSpeed(playback,playback.speed||1);changeView('shows');}}
$('#version').onclick=()=>modal(patchesHTML());
$('#brand-home').onclick=e=>{e.preventDefault();changeView('map');};
$('#new-game').onclick=()=>$('#reset').click();
$('#new-events').onclick=()=>{journalPinnedIds=null;$('#main').scrollTop=0;renderJournal();};
$('#hide-rest').checked=hideRest;$('#show-archives').checked=showArchives;$('#archive-threshold').value=world.archiveThreshold;
for(const checkbox of $$('#journal-types input[value]'))checkbox.checked=journalTypes.has(checkbox.value);
$('#journal-types').onchange=e=>{if(e.target.id==='hide-rest')hideRest=e.target.checked;else if(e.target.checked)journalTypes.add(e.target.value);else journalTypes.delete(e.target.value);journalPinnedIds=null;renderJournal();saveUI();};
$('#show-archives').onchange=e=>{showArchives=e.target.checked;catalogueLimit=50;renderJournal();renderProfile();saveUI();};
$('#archive-threshold').onchange=e=>{world.archiveThreshold=clamp(Number(e.target.value));e.target.value=world.archiveThreshold;save();notify('Seuil appliqué aux prochaines chansons. Les anciennes restent conservées.');};
$('#show-speed').onchange=e=>showSpeed=Number(e.target.value);
$('#show-pause').onclick=()=>{if(playback.speed===0)setPlaybackSpeed(playback,playback.resumeSpeed);else showPaused=!showPaused;showBudget=0;renderShows();};
$('#sound').onchange=async e=>{soundEnabled=e.target.checked&&await enableAudio();e.target.checked=soundEnabled;};
$('#reduced-effects').onchange=e=>{reducedEffects=e.target.checked;saveUI();};
$('#stage').onclick=e=>{const show=world.performance;if(!show)return;const r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)*900/r.width,y=(e.clientY-r.top)*650/r.height;const fan=[...show.fans].sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];if(fan&&Math.hypot(fan.x-x,fan.y-y)<50){selectedFan=fan.id;renderShows();}};
$('#stage').onkeydown=e=>{if(!world.performance||!['ArrowRight','ArrowLeft'].includes(e.key))return;e.preventDefault();const fans=world.performance.fans,index=fans.findIndex(f=>f.id===selectedFan);selectedFan=fans[(index+(e.key==='ArrowRight'?1:fans.length-1)+fans.length)%fans.length].id;renderShows();};
