 if(el.id==='replay-show')launchPreview(true);
 if(el.dataset.advanceBooking){const r=advanceToBooking(world,el.dataset.advanceBooking);notify(r.message);showPaused=false;setPlaybackSpeed(playback,1);render();changeView('shows');save();}
 if(el.dataset.cancelBooking)submit({type:'cancelBooking',bookingId:el.dataset.cancelBooking});
 if(el.dataset.archiveSong){submit({type:'archive',songId:Number(el.dataset.archiveSong),restore:el.dataset.restoreSong==='yes'});renderJournal();}
 if(el.dataset.revive)submit({type:'revive',groupId:el.dataset.revive});
 if(el.hasAttribute('data-toggle-archives')){showArchives=!showArchives;$('#show-archives').checked=showArchives;renderProfile();if(view==='journal')renderJournal();saveUI();}
 if(el.id==='more-songs'){catalogueLimit+=50;renderJournal();}
 if(el.id==='more-profile-songs'){profileSongLimit+=30;renderProfileSongs(current());}
 if(el.id==='new-season'){showingPerformance=false;const r=newSeason(world);notify(r.message);showPlan.opportunityId=null;renderShows();save();}
